DO
$do$
BEGIN 
  IF NOT (SELECT EXISTS(SELECT 1 FROM information_schema.schemata 
              WHERE schema_name = 'private'))
     OR obj_description('private'::regnamespace, 'pg_namespace') is null
     OR obj_description('private'::regnamespace, 'pg_namespace')::bigint < '1629907327'::bigint THEN
    
    RAISE LOG 'Migrating 1629907327.sql';
create table "public"."embeds" (
    "id" integer generated by default as identity not null,
    "url" text not null,
    "title" text,
    "description" text,
    "image" character varying(255),
    "image_sizes" jsonb,
    "response" jsonb,
    "created_at" timestamp with time zone default now(),
    "updated_at" timestamp with time zone default now()
);


drop extension if exists "pg_stat_statements";

CREATE INDEX embed_lookup ON public.embeds USING btree (url);

CREATE UNIQUE INDEX embeds_pkey ON public.embeds USING btree (id);

alter table "public"."embeds" add constraint "embeds_pkey" PRIMARY KEY using index "embeds_pkey";

    COMMENT ON SCHEMA private IS '1629907327';
  END IF;
END;
$do$;
